//! The generated files: Rust stubs, zeroed C data and C stubs for the variadic functions.
//!
//! Output depends only on the imports, sorted by symbol, so a rerun with no change writes the same bytes.

use std::fmt::Write as _;

use super::classify::{Class, Import};
use super::include::Include;

const NOTICE: &str = "Generated by `ferrite-dev stubs`; do not edit.";

/// The sections the unimplemented data lives in, writable and read-only, with their assembler flags. Each
/// name is a C identifier, so the linker keeps it an output section of its own; the lab maps its pages
/// no-access, so a read faults instead of returning zero.
const DATA_SECTIONS: [(&str, bool, &str); 2] =
    [("lx_unimplemented", false, "\\\"aw\\\",@nobits"), ("lx_unimplemented_ro", true, "\\\"a\\\",@nobits")];

/// The C size of a variable's storage: an array without a length gets one element.
fn size_of(import: &Import) -> String {
    match import.class {
        Class::Data { open_array: true, .. } => format!("sizeof({}[0])", import.symbol),
        _ => format!("sizeof({})", import.symbol),
    }
}

fn sorted(imports: &[Import], wanted: impl Fn(&Class) -> bool) -> Vec<&Import> {
    let mut chosen: Vec<_> = imports.iter().filter(|import| wanted(&import.class)).collect();
    chosen.sort_by(|a, b| a.symbol.cmp(&b.symbol));
    chosen
}

fn declared_in(import: &Import) -> String {
    import.header.as_ref().map_or_else(String::new, |header| format!(", declared in `{}`", header.name))
}

/// `src/stubs/generated.rs` of `ferrite-lkpi`: one stub per function, seams included.
pub fn rust_stubs(imports: &[Import]) -> String {
    let mut out = format!("//! {NOTICE}\n");
    let unknown = sorted(imports, |class| *class == Class::Unknown);
    if !unknown.is_empty() {
        out.push('\n');
    }
    for import in unknown {
        let _ = writeln!(out, "// unclassified: {}", import.symbol);
    }
    let stubs = sorted(imports, |class| matches!(class, Class::Function | Class::Seam { .. }));
    if stubs.is_empty() {
        return out;
    }
    out.push_str("\nuse crate::trace_and_stop;\n");
    for import in stubs {
        let symbol = &import.symbol;
        let _ = write!(out, "\n/// `{}`{}.\n", import.prototype, declared_in(import));
        if let Class::Seam { cut } = &import.class {
            let _ = writeln!(out, "/// Defined only in the cut `{cut}`.");
        }
        let ident = rust_ident(symbol);
        let _ = write!(
            out,
            "#[unsafe(no_mangle)]\npub unsafe extern \"sysv64\" fn {ident}() -> ! {{\n    trace_and_stop(c\"{symbol}\")\n}}\n"
        );
    }
    out
}

/// `symbol` as a Rust identifier: a C name that is a Rust keyword (`yield`) is written raw, which
/// leaves the exported symbol unchanged.
fn rust_ident(symbol: &str) -> String {
    const KEYWORDS: [&str; 49] = [
        "as", "async", "await", "break", "const", "continue", "crate", "dyn", "else", "enum", "extern", "false", "fn",
        "for", "gen", "if", "impl", "in", "let", "loop", "match", "mod", "move", "mut", "pub", "ref", "return",
        "static", "struct", "trait", "true", "type", "unsafe", "use", "where", "while", "abstract", "become", "box",
        "do", "final", "macro", "override", "priv", "try", "typeof", "unsized", "virtual", "yield",
    ];
    if KEYWORDS.contains(&symbol) { format!("r#{symbol}") } else { symbol.to_owned() }
}

/// `glue/generated_data.c`: storage for each variable, sized and aligned by its declared type, between
/// page-aligned markers in its section of [`DATA_SECTIONS`], and a table naming each for the lab's fault
/// report. The storage is laid out by `asm` statements, which the compiler keeps in order where it would
/// reorder C definitions. The headers are not all self-contained, so it includes all of `headers` in the
/// order the sources first meet them.
pub fn data_c(imports: &[Import], headers: &[Include]) -> String {
    let data = sorted(imports, |class| matches!(class, Class::Data { .. }));
    let mut out = format!(
        "/* {NOTICE} */\n/* Storage for the kernel data the Linux C imports and the shim has not implemented. */\n\n"
    );
    for header in headers {
        let _ = writeln!(out, "{}", header.directive());
    }
    out.push_str(
        "\n#define LX_MARK(name) asm volatile(\".globl \" #name \"\\n.balign 4096\\n\" #name \":\")\n\
         #define LX_DATA(sym, size) asm volatile(\".globl \" #sym \"\\n.type \" #sym \",@object\\n.balign %c1\\n\" \\\n\
         \t#sym \":\\n.zero %c0\\n.size \" #sym \", %c0\" :: \"i\"(size), \"i\"(__alignof__(sym)))\n\n\
         __attribute__((used)) static void lx_unimplemented_layout(void)\n{\n",
    );
    for (section, read_only, flags) in DATA_SECTIONS {
        let _ = writeln!(out, "\tasm volatile(\".pushsection {section},{flags}\");");
        let _ = writeln!(out, "\tLX_MARK({section}_begin);");
        for import in
            data.iter().filter(|import| matches!(import.class, Class::Data { read_only: r, .. } if r == read_only))
        {
            let _ = writeln!(out, "\tLX_DATA({}, {});", import.symbol, size_of(import));
        }
        let _ = writeln!(out, "\tLX_MARK({section}_end);");
        out.push_str("\tasm volatile(\".popsection\");\n");
    }
    out.push_str(
        "}\n\nstruct lx_data_symbol { const char *name; const void *address; unsigned long size; };\n\n\
         const struct lx_data_symbol lx_unimplemented_data[] = {\n",
    );
    for import in &data {
        let symbol = &import.symbol;
        let _ = writeln!(out, "\t{{ \"{symbol}\", &{symbol}, {} }},", size_of(import));
    }
    let _ = writeln!(out, "}};\nconst unsigned long lx_unimplemented_data_count = {};", data.len());
    out
}

/// `glue/generated_variadic.c`: a trace-and-stop definition per variadic function.
pub fn variadic_c(imports: &[Import]) -> String {
    let mut out = format!(
        "/* {NOTICE} */\n/* Rust cannot define variadic functions, so these call into ferrite-lkpi. */\n\n\
         extern void lx_stub_hit(const char *name) __attribute__((noreturn));\n"
    );
    for import in sorted(imports, |class| *class == Class::Variadic) {
        let symbol = &import.symbol;
        let _ = write!(
            out,
            "\n/* `{}`{}. */\nvoid {symbol}(void)\n{{\n\tlx_stub_hit(\"{symbol}\");\n}}\n",
            import.prototype,
            declared_in(import)
        );
    }
    out
}

#[cfg(test)]
mod tests {
    use assert2::check;

    use super::*;

    fn import(symbol: &str, class: Class, prototype: &str, header: Option<&str>) -> Import {
        let header = header.map(|name| Include { quoted: false, name: name.to_owned() });
        Import { symbol: symbol.to_owned(), class, prototype: prototype.to_owned(), header }
    }

    fn headers() -> Vec<Include> {
        vec![
            Include { quoted: false, name: "linux/types.h".to_owned() },
            Include { quoted: true, name: "linux/net/core.h".to_owned() },
        ]
    }

    fn sample() -> Vec<Import> {
        vec![
            import("mutex_lock", Class::Function, "void mutex_lock(struct mutex *)", Some("linux/mutex.h")),
            import("jiffies", Class::Data { read_only: false, open_array: false }, "", Some("linux/jiffies.h")),
            import(
                "nl80211_notify",
                Class::Seam { cut: "net/wireless/nl80211.c".into() },
                "void nl80211_notify(int)",
                Some("linux/nl80211.h"),
            ),
            import("_printk", Class::Variadic, "int _printk(const char *, ...)", Some("linux/printk.h")),
            import("page_offset_base", Class::Data { read_only: true, open_array: true }, "", Some("asm/page_64.h")),
            import("__x86_return_thunk", Class::Unknown, "", None),
            import("memcpy", Class::Host, "", None),
            import("yield", Class::Function, "void yield(void)", Some("linux/sched.h")),
        ]
    }

    #[test]
    fn rust_stubs_carry_the_prototype_and_stop_by_name() {
        let text = rust_stubs(&sample());
        check!(text.contains("// unclassified: __x86_return_thunk\n"));
        check!(text.contains(
            "/// `void mutex_lock(struct mutex *)`, declared in `linux/mutex.h`.\n#[unsafe(no_mangle)]\npub unsafe extern \"sysv64\" fn mutex_lock() -> ! {\n    trace_and_stop(c\"mutex_lock\")\n}\n"
        ));
        check!(text.contains("/// Defined only in the cut `net/wireless/nl80211.c`.\n"));
        check!(!text.contains("_printk"));
        check!(!text.contains("memcpy"));
        check!(text.contains("fn r#yield() -> ! {\n    trace_and_stop(c\"yield\")\n}"));
    }

    #[test]
    fn data_sits_between_the_page_aligned_markers_and_is_listed_by_name() {
        let text = data_c(&sample(), &headers());
        check!(text.contains("#include <linux/types.h>\n#include \"linux/net/core.h\"\n"));
        let at = |needle: &str| text.find(needle);
        let (begin, end) = (at("LX_MARK(lx_unimplemented_begin)"), at("LX_MARK(lx_unimplemented_end)"));
        let (ro_begin, ro_end) = (at("LX_MARK(lx_unimplemented_ro_begin)"), at("LX_MARK(lx_unimplemented_ro_end)"));
        let (writable, read_only) =
            (at("LX_DATA(jiffies, sizeof(jiffies))"), at("LX_DATA(page_offset_base, sizeof(page_offset_base[0]))"));
        check!(begin.is_some() && begin < writable && writable < end);
        check!(end < ro_begin && ro_begin < read_only && read_only < ro_end);
        check!(text.contains("\t{ \"jiffies\", &jiffies, sizeof(jiffies) },\n"));
        check!(text.contains("lx_unimplemented_data_count = 2;"));
    }

    #[test]
    fn variadic_stubs_call_the_shared_hook() {
        let text = variadic_c(&sample());
        check!(text.contains("/* `int _printk(const char *, ...)`, declared in `linux/printk.h`. */\nvoid _printk(void)\n{\n\tlx_stub_hit(\"_printk\");\n}\n"));
        check!(!text.contains("mutex_lock"));
    }

    #[test]
    fn output_does_not_depend_on_import_order() {
        let mut reversed = sample();
        reversed.reverse();
        check!(rust_stubs(&sample()) == rust_stubs(&reversed));
        check!(data_c(&sample(), &headers()) == data_c(&reversed, &headers()));
        check!(variadic_c(&sample()) == variadic_c(&reversed));
    }

    #[test]
    fn a_rust_file_with_no_stubs_has_no_unused_import() {
        check!(!rust_stubs(&[]).contains("use crate"));
    }
}
